package com.campus.student.infrastructure.persistence;
import java.util.*; import com.campus.student.application.StudentManagementService.ConcurrentStudentModificationException; import com.campus.student.domain.*; import com.campus.student.infrastructure.persistence.entity.StudentEntity; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional;
@Repository class StudentPersistenceAdapter implements StudentRepository { private final StudentJpaRepository repo; StudentPersistenceAdapter(StudentJpaRepository repo){this.repo=repo;} @Transactional public Student save(Student s){return managed(repo.findById(s.id()).orElseGet(()->new StudentEntity(s.id())),s);} @Transactional public Student saveMutation(Student s,long version){StudentEntity e=repo.findByIdForUpdate(s.id()).orElseThrow(); if(e.getRowVersion()!=version)throw new ConcurrentStudentModificationException(); return managed(e,s);} private Student managed(StudentEntity e,Student s){e.update(s.studentNumber(),s.fullName(),s.email(),s.identityUserId(),s.organizationUnitId(),s.status()); return map(repo.saveAndFlush(e));} @Transactional(readOnly=true) public Optional<Student> findById(UUID id){return repo.findById(id).map(this::map);} @Transactional(readOnly=true) public boolean existsByStudentNumber(String n){return repo.existsByStudentNumber(n);} @Transactional(readOnly=true) public List<Student> findAll(){return repo.findAll(org.springframework.data.domain.Sort.by("studentNumber")).stream().map(this::map).toList();} @Transactional(readOnly=true) public com.campus.shared.application.PageResult<Student> search(StudentSearch search){org.springframework.data.jpa.domain.Specification<StudentEntity> spec=(root,q,b)->{List<jakarta.persistence.criteria.Predicate> p=new ArrayList<>();if(search.query()!=null){String v="%"+search.query().toLowerCase(Locale.ROOT)+"%";p.add(b.or(b.like(b.lower(root.get("studentNumber")),v),b.like(b.lower(root.get("fullName")),v),b.like(b.lower(root.get("email")),v)));}if(search.status()!=null)p.add(b.equal(root.get("status"),search.status()));return b.and(p.toArray(jakarta.persistence.criteria.Predicate[]::new));};org.springframework.data.domain.Sort sort=org.springframework.data.domain.Sort.by(search.ascending()?org.springframework.data.domain.Sort.Direction.ASC:org.springframework.data.domain.Sort.Direction.DESC,search.sortField()).and(org.springframework.data.domain.Sort.by("id"));var page=repo.findAll(spec,org.springframework.data.domain.PageRequest.of(search.page(),search.size(),sort));return new com.campus.shared.application.PageResult<>(page.getContent().stream().map(this::map).toList(),page.getTotalElements());} private Student map(StudentEntity e){return new Student(e.getId(),e.getStudentNumber(),e.getFullName(),e.getEmail(),e.getIdentityUserId(),e.getOrganizationUnitId(),e.getStatus(),e.getRowVersion(),e.getCreatedAt(),e.getUpdatedAt());} }
